import warnings; warnings.filterwarnings('ignore')
def fit(fn, starts):
    best=None
    for s in starts:
        try:
            rr=least_squares(lambda q:(fn(q)-sigma)/sigma, s, max_nfev=3000)
            if np.all(np.isfinite(rr.fun)) and (best is None or rr.cost<best.cost): best=rr
        except Exception: pass
    if best is None: return None
    return best.x, np.mean((fn(best.x)-sigma)**2)/np.var(sigma)
